use ibapi::prelude::*;

pub struct TwsConnection {
    client: Client,
}

impl TwsConnection {
    pub async fn new(host: &str, port: u16, client_id: i32) -> Result<Self, Box<dyn std::error::Error>> {
        let connection_url = format!("{}:{}", host, port);
        let client = Client::connect(&connection_url, client_id)?;
        println!("Successfully connected to TWS at {}", connection_url);

        Ok(TwsConnection { client })
    }

    pub fn client(&self) -> &Client {
        &self.client
    }
}

