use ibxrust::connection::TwsConnection;

#[tokio::main]
async fn main() {
    let host = "127.0.0.1";
    let port = 7500;
    let client_id = 100;

    match TwsConnection::new(host, port, client_id).await {
        Ok(_connection) => {
            println!("Phase 1 Complete: Successfully established connection to TWS");
        }
        Err(e) => {
            eprintln!("Failed to connect to TWS: {}", e);
            std::process::exit(1);
        }
    }
}

